BATCH_ITEMS:
1. CHK-0121: "What is the impact on the pairing check if non-subgroup points are accepted?"
   - severity: Critical, property: PROP-W5B14-12, bug_class: Cryptographic Forgery
2. CHK-0122: "Can malicious P2P peer bypass subgroup checks via crafted DataColumnSidecar?"
   - severity: Critical, property: PROP-W5B14-12, bug_class: Subgroup Validation Bypass
3. CHK-0123: "Does verify_cell_kzg_proof_batch assume inputs have passed subgroup validation?"
   - severity: High, property: PROP-W5B14-12, bug_class: Implicit Trust Assumption
4. CHK-0124: "Which cryptographic library implements the BLS12-381 subgroup check, and is it correct?"
   - severity: High, property: PROP-W5B14-12, bug_class: Third-Party Library Validation
5. CHK-0125: "Does commitment deduplication in verify_cell_kzg_proof_batch preserve semantic equivalence?"
   - severity: Critical, property: PROP-W5B14-13, bug_class: Index Mapping Correctness

ADVERSARIAL CONTEXT:
An attacker can submit DataColumnSidecar messages via P2P gossip containing 48-byte values for KzgCommitments[] and KzgProofs[] that are valid curve points on BLS12-381 but NOT in the G1 prime-order subgroup. Goal: forge data availability proofs or cause incorrect pairing verification.

FULL CODE CONTEXT:

=== ENTRY POINT: beacon-chain/sync/validate_data_column.go (lines 30-227) ===
func (s *Service) validateDataColumn(ctx context.Context, pid peer.ID, msg *pubsub.Message) (pubsub.ValidationResult, error) {
    // Always accept messages our own messages.
    if pid == s.cfg.p2p.PeerID() { return pubsub.ValidationAccept, nil }
    // Ignore messages during initial sync.
    if s.cfg.initialSync.Syncing() { return pubsub.ValidationIgnore, nil }
    // Reject messages with a nil topic.
    if msg.Topic == nil { return pubsub.ValidationReject, p2p.ErrInvalidTopic }
    // Decode the message, reject if it fails.
    m, err := s.decodePubsubMessage(msg)
    dcsc, ok := m.(*eth.DataColumnSidecar)
    roDataColumn, err := blocks.NewRODataColumn(dcsc)
    roDataColumns := []blocks.RODataColumn{roDataColumn}
    verifier := s.newColumnsVerifier(roDataColumns, verification.GossipDataColumnSidecarRequirements)
    // [REJECT] verify_data_column_sidecar(sidecar) - ValidFields() calls VerifyDataColumnSidecar
    if err := verifier.ValidFields(); err != nil { return pubsub.ValidationReject, err }
    // ... subnet, slot, parent, proposer sig checks ...
    // [REJECT] verify_data_column_sidecar_kzg_proofs(sidecar)
    validationResult, err := s.validateWithKzgBatchVerifier(ctx, roDataColumns)
    // ...
    return pubsub.ValidationAccept, nil
}

=== VerifyDataColumnSidecar (p2p_interface.go lines 34-52) ===
func VerifyDataColumnSidecar(sidecar blocks.RODataColumn) error {
    numberOfColumns := params.BeaconConfig().NumberOfColumns
    if sidecar.Index >= numberOfColumns { return ErrIndexTooLarge }
    if len(sidecar.KzgCommitments) == 0 { return ErrNoKzgCommitments }
    if len(sidecar.Column) != len(sidecar.KzgCommitments) || len(sidecar.Column) != len(sidecar.KzgProofs) {
        return ErrMismatchLength
    }
    return nil
    // NOTE: NO subgroup or curve validation of KzgCommitments/KzgProofs bytes here!
    // Only checks: index range, non-empty commitments, length consistency
}

=== VerifyDataColumnsSidecarKZGProofs (p2p_interface.go lines 61-93) ===
func VerifyDataColumnsSidecarKZGProofs(sidecars []blocks.RODataColumn) error {
    count := 0
    for _, sidecar := range sidecars { count += len(sidecar.Column) }
    commitments := make([]kzg.Bytes48, 0, count)
    indices := make([]uint64, 0, count)
    cells := make([]kzg.Cell, 0, count)
    proofs := make([]kzg.Bytes48, 0, count)
    for _, sidecar := range sidecars {
        for i := range sidecar.Column {
            commitments = append(commitments, kzg.Bytes48(sidecar.KzgCommitments[i]))
            indices = append(indices, sidecar.Index)
            cells = append(cells, kzg.Cell(sidecar.Column[i]))
            proofs = append(proofs, kzg.Bytes48(sidecar.KzgProofs[i]))
        }
    }
    // Direct byte cast - no subgroup check at Go application layer
    verified, err := kzg.VerifyCellKZGProofBatch(commitments, indices, cells, proofs)
    if err != nil { return errors.Wrap(err, "verify cell KZG proof batch") }
    if !verified { return ErrInvalidKZGProof }
    return nil
}

=== VerifyCellKZGProofBatch (kzg.go lines 98-106) ===
func VerifyCellKZGProofBatch(commitmentsBytes []Bytes48, cellIndices []uint64, cells []Cell, proofsBytes []Bytes48) (bool, error) {
    ckzgCells := make([]ckzg4844.Cell, len(cells))
    for i := range cells { ckzgCells[i] = ckzg4844.Cell(cells[i]) }
    // Delegates entirely to c-kzg-4844 v2.1.1 C library
    return ckzg4844.VerifyCellKZGProofBatch(commitmentsBytes, cellIndices, ckzgCells, proofsBytes)
}

=== validateWithKzgBatchVerifier (batch_verifier.go lines 157-191) ===
func (s *Service) validateWithKzgBatchVerifier(ctx context.Context, dataColumns []blocks.RODataColumn) (pubsub.ValidationResult, error) {
    resChan := make(chan error)
    verificationSet := &kzgVerifier{dataColumns: dataColumns, resChan: resChan}
    s.kzgChan <- verificationSet
    // Context timeout: SecondsPerSlot duration
    select {
    case <-ctx.Done(): return pubsub.ValidationIgnore, ctx.Err()
    case err := <-resChan:
        if err != nil {
            // On batch failure, FALLBACK to unbatched verification
            return s.validateUnbatchedColumnsKzg(ctx, dataColumns)
        }
    }
    return pubsub.ValidationAccept, nil
}

func verifyKzgBatch(kzgBatch []*kzgVerifier) {
    // Collects ALL pending dataColumns from ALL queued kzgVerifier structs
    allDataColumns := make([]blocks.RODataColumn, 0, len(kzgBatch))
    for _, kzgVerifier := range kzgBatch { allDataColumns = append(allDataColumns, kzgVerifier.dataColumns...) }
    err := peerdas.VerifyDataColumnsSidecarKZGProofs(allDataColumns)
    // One shared error sent to ALL kzgVerifiers in batch
    for _, verifier := range kzgBatch { verifier.resChan <- verificationErr }
}

LIBRARY: github.com/ethereum/c-kzg-4844/v2 v2.1.1 (C library via CGo bindings)
- Key property: c-kzg-4844's VerifyCellKZGProofBatch internally deserializes bytes48 into G1 points
- BLS12-381 G1 deserialization in c-kzg-4844 uses blst library which DOES perform subgroup checks during deserialization
- The library validates: (1) point is on the curve, (2) point is in the G1 prime-order subgroup

COMMIT DEDUPLICATION (CHK-0125):
The VerifyDataColumnsSidecarKZGProofs in this code does NOT do commitment deduplication.
It passes ALL commitments directly: one per (sidecar, column) pair.
The deduplication described in the checklist item is in the underlying c-kzg-4844 library,
which internally handles the batched verification with randomized linear combination.
The current Go code does NOT implement commitment_indices mapping.

